<?php

declare(strict_types=1);

/**
 * Regenerates the .zst fixtures and manifest.json with the real `zstd` tool (the plaintexts are generated by
 * tests/Inputs.php, deterministically, and are not committed):
 *
 *     php tests/fixtures/generate.php
 *
 * manifest.json maps each fixture to the inputs (parts) whose concatenation it must decode to, and the SHA-256 of that
 * plaintext (a guard against the generator drifting).
 */

require __DIR__ . '/../../vendor/autoload.php';
require __DIR__ . '/../Inputs.php';
require __DIR__ . '/../Cli.php';

use Charm\Zstd\Tests\Cli;
use Charm\Zstd\Tests\Inputs;

if (!Cli::available()) {
    fwrite(STDERR, "The zstd command-line tool is needed to generate the fixtures.\n");
    exit(1);
}

// name => [parts, zstd options, piped]: a piped fixture is read from stdin, so its frame has no content size
$single = [
    'fast5' => ['text', '--fast=5'],
    'level1' => ['text', '-1'],
    'level3' => ['text', '-3'],
    'level3-check' => ['text', '-3 --check'],
    'level3-nocheck' => ['text', '-3 --no-check'],
    'level19' => ['text', '-19'],
    'ultra22' => ['text', '--ultra -22'],
    'long27' => ['text', '-3 --long=27'],
    'no-compress-literals' => ['text', '-3 --no-compress-literals'],
    'no-content-size' => ['text', '-3 --no-content-size'],
    'block4096' => ['text', '-3 -B4096'],
    'mixed-level1' => ['mixed', '-1'],
    'mixed-level3-check' => ['mixed', '-3 --check'],
    'mixed-level19' => ['mixed', '-19'],
    'mixed-block4096-check' => ['mixed', '-1 -B4096 --check'],
    'small-level3-check' => ['small', '-3 --check'],
    'small-level19-nocheck' => ['small', '-19 --no-check'],
    'small-level1-nocheck-rawlits' => ['small', '-1 --no-check --no-compress-literals'],
    'small-fast3-nocheck' => ['small', '--fast=3 --no-check'],
    'tiny-level3-check' => ['tiny', '-3 --check'],
    'tiny-level19-nocheck' => ['tiny', '-19 --no-check'],
];
$piped = [
    'piped' => ['text', '-5'],
    'piped-check' => ['mixed', '-3 --check'],
];

$manifest = [];
$frames = [];
$write = function (string $name, array $parts, string $zst) use (&$manifest): void {
    file_put_contents(__DIR__ . "/$name.zst", $zst);
    $plain = '';
    foreach ($parts as $p) {
        $plain .= Inputs::get($p);
    }
    $manifest[$name] = ['parts' => $parts, 'sha256' => hash('sha256', $plain), 'bytes' => strlen($plain)];
    printf("%-30s %8d bytes (plaintext %d)\n", "$name.zst", strlen($zst), strlen($plain));
};

foreach ($single as $name => [$part, $opts]) {
    $frames[$name] = Cli::compress(Inputs::get($part), $opts);
    $write($name, [$part], $frames[$name]);
}
foreach ($piped as $name => [$part, $opts]) {
    $frames[$name] = Cli::compressPiped(Inputs::get($part), $opts);
    $write($name, [$part], $frames[$name]);
}

// Concatenated frames; a skippable frame in front, between and after
$skip = static fn (int $magicLow, string $payload): string => pack('V', 0x184D2A50 + $magicLow) . pack('V', strlen($payload)) . $payload;
$write('concatenated', ['text', 'mixed', 'small'], $frames['level3-check'] . Cli::compressPiped(Inputs::get('mixed'), '-1') . Cli::compress(Inputs::get('small'), '-19'));
$write('skippable', ['text', 'small'], $skip(0, 'a skippable frame') . $frames['level3-check'] . $skip(15, '') . $frames['small-level3-check'] . $skip(7, str_repeat("\xFF", 1000)));

// Frames written by this package's own compressor (Huffman literals, 1 and 4 streams, FSE-compressed tables, a block of literals only),
// each checked with `zstd -d` before it is committed, so that the tests which do not run the tool still decode them
foreach (['ours-text' => 'text', 'ours-mixed' => 'mixed', 'ours-skew' => 'skew', 'ours-lits' => 'lits', 'ours-tiny' => 'tiny'] as $name => $part) {
    $zst = \Charm\Zstd\Zstd::compress(Inputs::get($part));
    if (Cli::decompress($zst) !== Inputs::get($part)) {
        fwrite(STDERR, "zstd -d does not accept our output for $part\n");
        exit(1);
    }
    $write($name, [$part], $zst);
}

// A frame that holds nothing
$write('empty', [], Cli::compress('', ''));

ksort($manifest);
file_put_contents(__DIR__ . '/manifest.json', json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n");
echo 'Wrote ', count($manifest), " fixtures, ", Cli::version(), "\n";
